INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2600, 'expedient', '/''ɪkˈspiːdiənt/', 'adjective', '{"zh-TW":["便利的；得當的"],"en":["convenient and practical, even if improper or immoral; based on what is useful rather than what is right"]}', NULL, 'expedient solution / politically expedient / expedient choice', '[{"en":"The company chose the most expedient solution rather than the most ethical one.","zh-TW":"公司選擇了最便利的解決方案，而不是最道德的。"},{"en":"An expedient decision might solve the immediate problem but create future complications.","zh-TW":"一個便利的決定可能解決了眼前的問題，但會造成未來的複雜性。"}]', '{"noun":"expediency","adverb":"expediently"}', NULL, 3, 2600, NULL),
(2601, 'expedient solution', '/''ɪkˌspiːdiənt səˌluːʃən/', 'noun', '{"zh-TW":["權宜之計；便宜行事的解決方案"],"en":["a solution that is convenient and practical but not always the most ethical or principled"]}', NULL, 'choose an expedient solution / short-term expedient solution', '[{"en":"The company chose an expedient solution to the problem rather than addressing the root cause.","zh-TW":"公司選擇了對問題的權宜之計，而不是解決根本原因。"},{"en":"An expedient solution may solve the immediate crisis but create bigger problems later.","zh-TW":"權宜之計可能解決了眼前的危機，但以後會製造更大的問題。"}]', NULL, NULL, 5, 2601, NULL),
(2602, 'expedite', '/ˈekspədaɪt/', 'verb', '{"zh-TW":["加快；促進"],"en":["to make a process happen more quickly"]}', NULL, 'expedite the process/delivery', '[{"en":"We can expedite shipping for an extra fee.","zh-TW":"我們可以加收費用加快出貨。"},{"en":"Please expedite the approval process.","zh-TW":"請加快審批流程。"}]', '{"verb":"expedite","adjective":"expedited"}', NULL, 3, 2602, 682),
(2603, 'expedited shipping', '/''ekspɪdaɪtɪd ˌʃɪpɪŋ/', 'noun', '{"zh-TW":["加急運輸；快速配送"],"en":["a faster shipping option that delivers goods more quickly than standard shipping for an additional fee"]}', NULL, 'choose expedited shipping / expedited shipping cost / offer expedited shipping', '[{"en":"She chose expedited shipping to ensure the birthday gift arrived on time.","zh-TW":"她選擇了加急運輸，確保生日禮物準時到達。"},{"en":"Expedited shipping costs three times more but guarantees delivery within two days.","zh-TW":"加急運輸的費用是普通運輸的三倍，但保證在兩天內送達。"}]', NULL, NULL, 5, 2603, NULL),
(2604, 'expedition', '/''ekspɪˌdɪʃən/', 'noun', '{"zh-TW":["遠征；考察旅行"],"en":["a journey undertaken for a specific purpose, especially exploration or research"]}', NULL, 'lead an expedition / join an expedition / polar expedition', '[{"en":"The scientific expedition discovered several new plant species.","zh-TW":"這次科學考察旅行發現了幾種新植物。"},{"en":"He organized an expedition to the summit of Mount Everest.","zh-TW":"他組織了一次攀登珠穆朗瑪峰的遠征。"}]', NULL, NULL, 4, 2604, NULL),
(2605, 'expenditure', '/ɪkˈspendɪtʃər/', 'noun', '{"zh-TW":["支出；開支"],"en":["the action of spending money; an amount spent"]}', NULL, 'capital/government expenditure', '[{"en":"Total expenditure exceeded the budget.","zh-TW":"總支出超過了預算。"},{"en":"Capital expenditure was reduced this year.","zh-TW":"今年資本支出減少了。"}]', '{"noun":"expenditure","verb":"expend"}', NULL, 4, 2605, 568),
(2606, 'expenditure control', '/ɪkˈspendɪtʃər kənˈtroʊl/', 'noun', '{"zh-TW":["支出控制"],"en":["managing and limiting how funds are spent within a budget"]}', NULL, 'tighten expenditure control / expenditure control measures', '[{"en":"Expenditure control was tightened after the budget overrun.","zh-TW":"預算超支後加強了支出控制。"},{"en":"Monthly expenditure control reports were submitted to the finance committee.","zh-TW":"每月支出控制報告提交給財務委員會。"}]', NULL, NULL, 5, 2606, NULL),
(2607, 'expenditure plan', '/ɪkˈspendɪtʃər plæn/', 'noun', '{"zh-TW":["支出計劃"],"en":["a document outlining planned spending activities and timing"]}', NULL, 'prepare an expenditure plan / approve the expenditure plan', '[{"en":"The department submitted its expenditure plan for the next fiscal year.","zh-TW":"部門提交了下一財政年度的支出計劃。"},{"en":"The expenditure plan was revised to align with budget constraints.","zh-TW":"支出計劃修訂以符合預算限制。"}]', NULL, NULL, 5, 2607, NULL),
(2608, 'expenditure review', '/ɪkˈspendɪtʃər rɪˈvjuː/', 'noun', '{"zh-TW":["支出審查"],"en":["an assessment of spending to identify inefficiencies or savings"]}', NULL, 'conduct an expenditure review / annual expenditure review', '[{"en":"The expenditure review revealed 10% in wasteful spending.","zh-TW":"支出審查揭示了10%的浪費性支出。"},{"en":"All departments participated in the annual expenditure review.","zh-TW":"所有部門參與了年度支出審查。"}]', NULL, NULL, 5, 2608, NULL),
(2609, 'expense', '/ɪkˈspens/', 'noun', '{"zh-TW":["費用；開支"],"en":["the cost of something; money spent"]}', NULL, 'at the expense of / business expense', '[{"en":"Travel expenses will be reimbursed.","zh-TW":"差旅費用將報銷。"},{"en":"Profit should not come at the expense of quality.","zh-TW":"利潤不應以犧牲品質為代價。"}]', '{"noun":"expense","adjective":"expensive"}', NULL, 3, 2609, 121),
(2610, 'expense account', '/ɪkˈspens əˈkaʊnt/', 'noun', '{"zh-TW":["費用帳戶；業務費用帳"],"en":["an account charged with approved work-related expenditures"]}', NULL, 'charge to expense account / expense account policy', '[{"en":"Business meals and travel can be charged to the expense account.","zh-TW":"商務餐和差旅費可以記入費用帳戶。"},{"en":"The expense account must be reconciled with receipts monthly.","zh-TW":"費用帳戶必須每月與收據進行對帳。"}]', NULL, NULL, 5, 2610, NULL),
(2611, 'expense claim', '/ɪkˈspens kleɪm/', 'noun', '{"zh-TW":["費用報銷申請"],"en":["a request by an employee to be reimbursed for work-related expenses"]}', NULL, 'submit an expense claim / approve an expense claim', '[{"en":"All expense claims must be submitted within 30 days of the expense.","zh-TW":"所有費用報銷申請必須在費用發生後30天內提交。"},{"en":"The expense claim was rejected as it lacked supporting receipts.","zh-TW":"費用報銷申請因缺少支持收據而被拒絕。"}]', NULL, NULL, 5, 2611, NULL),
(2612, 'expense management', '/ɪkˈspɛns ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["費用管理"],"en":["the process of controlling business spending"]}', NULL, 'improve expense management / expense management software', '[{"en":"Expense management software helps track all company spending.","zh-TW":"費用管理軟體有助於追蹤所有公司支出。"},{"en":"Effective expense management improves the company''s bottom line.","zh-TW":"有效的費用管理改善了公司的底線。"}]', NULL, NULL, 5, 2612, NULL),
(2613, 'expense ratio', '/ɪkˈspens ˈreɪʃioʊ/', 'noun', '{"zh-TW":["費用比率"],"en":["the percentage of fund assets used to cover management and operating expenses"]}', NULL, 'compare expense ratios / low expense ratio', '[{"en":"Index funds typically have a much lower expense ratio than active funds.","zh-TW":"指數基金的費用比率通常遠低於主動管理基金。"},{"en":"The expense ratio directly reduces investor returns over time.","zh-TW":"費用比率隨時間推移直接降低了投資者回報。"}]', NULL, NULL, 5, 2613, NULL),
(2614, 'expense reimbursement', '/ɪkˈspens ˌriːɪmˈbɜːrsmənt/', 'noun', '{"zh-TW":["費用報銷"],"en":["the repayment by an employer of work-related expenses paid by an employee"]}', NULL, 'submit expense reimbursement / expense reimbursement policy', '[{"en":"All expense reimbursement claims must be submitted with receipts.","zh-TW":"所有費用報銷申請必須附上收據提交。"},{"en":"The company updated its expense reimbursement policy for travel.","zh-TW":"公司更新了差旅費用報銷政策。"}]', NULL, NULL, 5, 2614, NULL),
(2615, 'expense report', '/ɪkˈspɛns rɪˈpɔːrt/', 'noun', '{"zh-TW":["費用報告；報銷單"],"en":["a document listing work-related expenses for reimbursement"]}', NULL, 'submit an expense report / approve an expense report', '[{"en":"Please submit your expense report by the end of the month.","zh-TW":"請在月底前提交您的費用報告。"},{"en":"All receipts must be attached to the expense report.","zh-TW":"所有收據必須附在費用報告上。"}]', NULL, NULL, 5, 2615, NULL),
(2616, 'expensive', 'ɪkˈspɛnsɪv', 'adjective', '{"zh-TW":["昂貴的；高價的","費用高的"],"en":["costing a lot of money","high-priced"]}', NULL, 'expensive product/too expensive', '[{"en":"This software is too expensive for our budget.","zh-TW":"這款軟體對我們的預算來說太貴了。"}]', '{"noun":"expense","adverb":"expensively"}', NULL, 3, 2616, NULL),
(2617, 'experience', '/ɪkˈspɪriəns/', 'noun / verb', '{"zh-TW":["經驗；體驗"],"en":["knowledge gained through involvement; to encounter"]}', NULL, 'work/customer experience', '[{"en":"Do you have experience in project management?","zh-TW":"你有項目管理經驗嗎？"},{"en":"Customers experienced technical difficulties.","zh-TW":"客戶遇到了技術困難。"}]', '{"noun":"experience","verb":"experience","adjective":"experienced"}', NULL, 4, 2617, 122),
(2618, 'experiment', '/ɪkˈsperɪmənt/', 'noun / verb', '{"zh-TW":["實驗；試驗"],"en":["a scientific test; to try something new"]}', NULL, 'conduct an experiment', '[{"en":"The team conducted an experiment to test the theory.","zh-TW":"團隊進行了實驗來測試理論。"},{"en":"We are experimenting with new marketing channels.","zh-TW":"我們正在嘗試新的行銷渠道。"}]', '{"noun":"experiment/experimentation","verb":"experiment","adjective":"experimental"}', NULL, 4, 2618, NULL),
(2619, 'expert', '/ˈekspɜːrt/', 'noun / adjective', '{"zh-TW":["專家；專業的"],"en":["a person with great knowledge in a subject"]}', NULL, 'industry/subject expert', '[{"en":"She is an expert in international trade.","zh-TW":"她是國際貿易專家。"},{"en":"We consulted an expert on tax law.","zh-TW":"我們諮詢了一位稅法專家。"}]', '{"noun":"expert/expertise","adjective":"expert"}', NULL, 2, 2619, NULL),
(2620, 'expert witness', '/ˈekspɜːrt ˈwɪtnɪs/', 'noun', '{"zh-TW":["專家證人"],"en":["a qualified professional who provides testimony in legal proceedings"]}', NULL, 'call an expert witness / expert witness report', '[{"en":"The company hired an expert witness to support its case.","zh-TW":"公司聘請了一名專家證人支持其案件。"},{"en":"The expert witness provided a detailed valuation report.","zh-TW":"專家證人提供了詳細的估值報告。"}]', NULL, NULL, 5, 2620, NULL),
(2621, 'expertise', 'ˌɛkspɜːrˈtiːz', 'noun', '{"zh-TW":["專業知識；技能","專長"],"en":["expert knowledge","a high level of skill"]}', NULL, 'domain expertise/technical expertise', '[{"en":"Her expertise in finance is valuable.","zh-TW":"她在財務方面的專業知識很有價值。"}]', '{"adjective":"expert","adverb":"expertly"}', NULL, 3, 2621, NULL),
(2622, 'expiration', '/ˌɛkspɪˈreɪʃən/', 'noun', '{"zh-TW":["到期；屆滿"],"en":["the end of the period during which something is valid"]}', NULL, 'contract expiration / expiration date', '[{"en":"The contract is approaching its expiration date.","zh-TW":"合約即將到期。"},{"en":"Renew your license before its expiration.","zh-TW":"請在到期前更新您的執照。"}]', '{"verb":"expire","adjective":"expired"}', NULL, 4, 2622, 356),
(2623, 'expire', '/ɪkˈspaɪər/', 'verb', '{"zh-TW":["到期；過期"],"en":["to come to the end of validity"]}', NULL, 'expire on/contract expires', '[{"en":"Your contract expires at the end of the month.","zh-TW":"你的合約月底到期。"},{"en":"The coupon expired yesterday.","zh-TW":"優惠券昨天過期了。"}]', '{"noun":"expiration/expiry","verb":"expire","adjective":"expired"}', NULL, 2, 2623, NULL),
(2624, 'explain', '/ɪkˈspleɪn/', 'verb', '{"zh-TW":["解釋；說明"],"en":["to make something clear"]}', NULL, 'explain how/why', '[{"en":"Can you explain the procedure?","zh-TW":"你能解釋一下流程嗎？"},{"en":"She explained why the project was delayed.","zh-TW":"她解釋了為什麼項目延遲了。"}]', '{"noun":"explanation","verb":"explain","adjective":"explanatory"}', NULL, 3, 2624, NULL),
(2625, 'explicit', '/ɪkˈsplɪsɪt/', 'adjective', '{"zh-TW":["明確的；清楚的"],"en":["stated clearly and in detail"]}', NULL, 'explicit instructions/consent', '[{"en":"The contract contains explicit terms.","zh-TW":"合約包含明確的條款。"},{"en":"You need explicit permission to proceed.","zh-TW":"你需要明確的許可才能繼續。"}]', '{"adjective":"explicit","adverb":"explicitly"}', NULL, 3, 2625, 683),
(2626, 'explicit cost', '/ɪkˈsplɪsɪt kɒst/', 'noun', '{"zh-TW":["顯性成本；明確成本"],"en":["a direct, clear, and easily measurable cost such as wages or rent"]}', NULL, 'calculate explicit costs / explicit vs implicit costs', '[{"en":"Rent and salaries are explicit costs that appear directly on financial statements.","zh-TW":"租金和薪資是直接出現在財務報表上的顯性成本。"},{"en":"Explicit costs are easier to track and control than implicit costs.","zh-TW":"顯性成本比隱性成本更容易追蹤和控制。"}]', '{"opposite":"implicit cost"}', NULL, 5, 2626, NULL),
(2627, 'explicitly', '/''ɪkˈsplɪsɪtli/', 'adverb', '{"zh-TW":["明確地；清楚地"],"en":["in a clear and detailed manner, leaving no room for confusion or doubt"]}', NULL, 'state explicitly / mention explicitly / explicitly require', '[{"en":"The contract explicitly states that late payments will incur a penalty fee.","zh-TW":"合同明確規定，逾期付款將產生罰款。"},{"en":"She explicitly instructed the team to avoid the use of informal language in reports.","zh-TW":"她明確指示團隊避免在報告中使用非正式語言。"}]', '{"adjective":"explicit"}', NULL, 4, 2627, NULL),
(2628, 'exploit', '/ɪkˈsplɔɪt/', 'verb', '{"zh-TW":["利用；開發"],"en":["to make full use of; to use unfairly"]}', NULL, 'exploit resources/opportunities', '[{"en":"We should exploit this market opportunity.","zh-TW":"我們應該利用這個市場機會。"},{"en":"The company exploited cheap labor.","zh-TW":"公司剝削了廉價勞動力。"}]', '{"noun":"exploitation","verb":"exploit"}', NULL, 3, 2628, NULL),
(2629, 'explore', '/ɪkˈsplɔːr/', 'verb', '{"zh-TW":["探索；調查"],"en":["to examine or investigate thoroughly"]}', NULL, 'explore options/possibilities', '[{"en":"Let''s explore all available options.","zh-TW":"讓我們探索所有可用的選項。"},{"en":"The team explored new business models.","zh-TW":"團隊探索了新的商業模式。"}]', '{"noun":"exploration/explorer","verb":"explore","adjective":"exploratory"}', NULL, 3, 2629, NULL),
(2630, 'exponential', '/ˌekspəˈnenʃəl/', 'adjective', '{"zh-TW":["指數的；急劇增長的"],"en":["involving an extremely rapid increase"]}', NULL, 'exponential growth / exponential curve / exponential rate', '[{"en":"The spread of the virus followed an exponential curve.","zh-TW":"病毒的傳播遵循指數曲線。"},{"en":"Computing power has grown at an exponential rate since the 1960s.","zh-TW":"自1960年代以來，計算能力以指數速率增長。"}]', '{"adverb":"exponentially","noun":"exponent"}', NULL, 4, 2630, NULL),
(2631, 'export', '/ˈekspɔːrt/', 'noun / verb', '{"zh-TW":["出口；輸出"],"en":["to sell goods to another country"]}', NULL, 'export goods/data', '[{"en":"Japan exports electronics worldwide.","zh-TW":"日本向全球出口電子產品。"},{"en":"Exports grew by 8% last year.","zh-TW":"去年出口增長了8%。"}]', '{"noun":"export/exporter","verb":"export"}', NULL, 2, 2631, 357),
(2632, 'export control', '/''ekspɔːrt kənˌtrəʊl/', 'noun', '{"zh-TW":["出口管制"],"en":["government regulations that restrict or control the export of certain goods and technologies"]}', NULL, 'comply with export controls / export control regulation / export control compliance', '[{"en":"Technology companies must comply with export controls for sensitive products.","zh-TW":"科技公司必須遵守敏感產品的出口管制。"},{"en":"Failure to comply with export controls can result in heavy fines and business restrictions.","zh-TW":"不遵守出口管制可能導致巨額罰款和業務限制。"}]', NULL, NULL, 5, 2632, NULL),
(2633, 'export financing', '/ˈekspɔːrt ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["出口融資"],"en":["financial products helping exporters fund international sales transactions"]}', NULL, 'arrange export financing / export financing facility', '[{"en":"Export financing allowed the company to offer extended payment terms to buyers.","zh-TW":"出口融資允許公司向買家提供延長的付款條款。"},{"en":"Government export financing agencies support national exporters competitively.","zh-TW":"政府出口融資機構支持本國出口商提高競爭力。"}]', NULL, NULL, 5, 2633, NULL),
(2634, 'export license', '/ˈekspɔːrt ˈlaɪsəns/', 'noun', '{"zh-TW":["出口許可證"],"en":["official approval required to export certain goods to specific countries"]}', NULL, 'obtain an export license / apply for an export license', '[{"en":"A special export license was required for the controlled technology.","zh-TW":"受管制技術需要特殊出口許可證。"},{"en":"The export license was delayed due to additional security checks.","zh-TW":"由於額外的安全檢查，出口許可證被延遲了。"}]', NULL, NULL, 5, 2634, NULL),
(2635, 'export subsidy', '/ˈekspɔːrt ˈsʌbsɪdi/', 'noun', '{"zh-TW":["出口補貼"],"en":["government financial support given to domestic producers to boost exports"]}', NULL, 'provide export subsidies / export subsidy program', '[{"en":"Export subsidies gave the domestic industry an unfair advantage.","zh-TW":"出口補貼給了國內產業不公平的優勢。"},{"en":"The WTO ruled that the export subsidies violated trade rules.","zh-TW":"世貿組織裁定出口補貼違反了貿易規則。"}]', '{"plural":"export subsidies"}', NULL, 5, 2635, NULL),
(2636, 'expose', '/ɪkˈspoʊz/', 'verb', '{"zh-TW":["暴露；揭發"],"en":["to make visible; to reveal","to make visible or reveal"]}', '{"prefix":{"text":"ex-","meaning":"out (出)"},"root":{"text":"pose","meaning":"put (放置)"},"logic":"把東西放到外面讓人看到，即「暴露」。"}', 'expose to risk/information; expose to / expose the truth', '[{"en":"Workers were exposed to harmful chemicals.","zh-TW":"工人暴露在有害化學品中。"},{"en":"The investigation exposed fraud in the company.","zh-TW":"調查揭發了公司的詐騙行為。"},{"en":"Children should not be exposed to violence.","zh-TW":"兒童不應暴露在暴力之下。"},{"en":"The journalist exposed the corruption scandal.","zh-TW":"記者揭發了貪腐醜聞。"}]', '{"noun":"exposure","verb":"expose","adjective":"exposed"}', NULL, 2, 2636, NULL),
(2637, 'expository', '/ɪkˈspɒzɪtəri/', 'adjective', '{"zh-TW":["說明的；闡述的"],"en":["intended to explain or describe something"]}', NULL, 'expository writing / expository essay / expository style', '[{"en":"Expository writing requires clarity and logical organization.","zh-TW":"說明性寫作需要清晰和邏輯組織。"},{"en":"The textbook uses an expository style to present complex theories.","zh-TW":"教科書使用說明性風格來呈現複雜的理論。"}]', NULL, NULL, 4, 2637, NULL),
(2638, 'exposure', 'ɪkˈspoʊʒər', 'noun', '{"zh-TW":["曝光；接觸","暴露"],"en":["experience or knowledge gained","public attention"]}', NULL, 'market exposure/brand exposure', '[{"en":"International exposure helps career growth.","zh-TW":"國際接觸有助於職業發展。"}]', '{"verb":"expose","adjective":"exposed"}', NULL, 3, 2638, 570),
(2639, 'exposure limit', '/ɪkˈspoʊʒər ˈlɪmɪt/', 'noun', '{"zh-TW":["敞口限額"],"en":["the maximum amount of financial risk allowed toward a single counterparty or asset"]}', NULL, 'set an exposure limit / breach an exposure limit', '[{"en":"The bank set a $20 million exposure limit per borrower.","zh-TW":"銀行為每個借款人設定了2000萬元的敞口限額。"},{"en":"Breach of an exposure limit triggers a mandatory risk reduction.","zh-TW":"突破敞口限額觸發了強制性的風險降低。"}]', NULL, NULL, 5, 2639, NULL),
(2640, 'expound', '/ɪkˈspaʊnd/', 'verb', '{"zh-TW":["詳細解說；闡述"],"en":["to present and explain a theory or idea in detail"]}', NULL, 'expound a theory / expound on a topic / expound ideas', '[{"en":"He expounded his theory of organizational behavior at the conference.","zh-TW":"他在會議上詳細闡述了他的組織行為理論。"},{"en":"The professor expounded on the economic implications of the policy.","zh-TW":"教授詳細解說了該政策的經濟含意。"}]', NULL, NULL, 3, 2640, NULL),
(2641, 'express checkout', '/ɪkˈsprɛs ˈtʃɛkaʊt/', 'noun', '{"zh-TW":["快速退房"],"en":["a quick check-out process, often without visiting the desk"]}', NULL, 'use express checkout / express checkout option', '[{"en":"Express checkout is available via the hotel app.","zh-TW":"快速退房可通過飯店應用程式辦理。"},{"en":"Leave your key card and use express checkout to save time.","zh-TW":"留下鑰匙卡並使用快速退房節省時間。"}]', NULL, NULL, 5, 2641, NULL),
(2642, 'express delivery', '/''ɪkˌspres dɪˌlɪvəri/', 'noun', '{"zh-TW":["快遞；快速遞送"],"en":["a courier service that guarantees delivery within a short time frame, often next day"]}', NULL, 'use express delivery / offer express delivery / express delivery tracking', '[{"en":"She chose express delivery to send the documents urgently to the client.","zh-TW":"她選擇快遞，緊急將文件發送給客戶。"},{"en":"Express delivery services are widely used by businesses for time-sensitive shipments.","zh-TW":"快遞服務被企業廣泛用於時間敏感的貨物。"}]', NULL, NULL, 5, 2642, NULL),
(2643, 'expropriation', '/eksˌprəʊpriˈeɪʃən/', 'noun', '{"zh-TW":["徵收；沒收"],"en":["the taking of private property by a government for public use"]}', NULL, 'risk of expropriation / land expropriation / expropriation without compensation', '[{"en":"The government ordered the expropriation of land to build a new highway.","zh-TW":"政府下令徵收土地以建設新高速公路。"},{"en":"Foreign investors feared expropriation without fair compensation.","zh-TW":"外國投資者擔心在沒有公平補償的情況下遭到徵收。"}]', '{"verb":"expropriate","adjective":"expropriated"}', NULL, 5, 2643, NULL),
(2644, 'extend', '/ɪkˈstend/', 'verb', '{"zh-TW":["延長；擴展","延伸；延長"],"en":["to make longer or larger"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tend","meaning":"stretch (伸展)"},"logic":"向外伸展，即「延伸」。"}', 'extend a deadline/contract; extend a deadline / extend an invitation', '[{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以將截止日期延長一週嗎？"},{"en":"The company extended its operations to Asia.","zh-TW":"公司將業務擴展到亞洲。"},{"en":"Can we extend the deadline by one week?","zh-TW":"我們可以把截止期限延長一週嗎？"},{"en":"The road extends for 200 kilometers.","zh-TW":"這條路延伸了200公里。"}]', '{"noun":"extension","verb":"extend","adjective":"extensive/extended","adjective2":"extended"}', NULL, 2, 2644, 123),
(2645, 'extension', 'ɪkˈstɛnʃən', 'noun', '{"zh-TW":["延期；延長","分機"],"en":["an additional period of time","a telephone number within a system"]}', NULL, 'request an extension/extension number', '[{"en":"Please call extension 204 for support.","zh-TW":"請撥打分機204以獲取支援。"}]', '{"verb":"extend","adjective":"extensible","adverb":"extensively"}', NULL, 3, 2645, 571),
(2646, 'extensive', '/ɪkˈstensɪv/', 'adjective', '{"zh-TW":["廣泛的；大量的"],"en":["covering a large area or having great range","covering a large area or having a wide scope"]}', '{"prefix":{"text":"ex-","meaning":"out (向外)"},"root":{"text":"tens","meaning":"stretch (伸展)"},"suffix":{"text":"-ive","meaning":"having quality (具有…特質)"},"logic":"具有向外伸展特質的，即「廣泛的」。"}', 'extensive experience/research; extensive research / extensive experience / extensive damage', '[{"en":"She has extensive experience in finance.","zh-TW":"她有豐富的金融經驗。"},{"en":"Extensive research was conducted.","zh-TW":"進行了廣泛的研究。"},{"en":"She has extensive experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"},{"en":"The storm caused extensive damage.","zh-TW":"暴風雨造成了大範圍的損害。"}]', '{"adjective":"extensive","adverb":"extensively","noun":"extent"}', NULL, 3, 2646, 873),
(2647, 'external', '/ɪkˈstɜːrnəl/', 'adjective', '{"zh-TW":["外部的；外在的"],"en":["coming from outside"]}', NULL, 'external factors/audit', '[{"en":"External factors affected the company''s performance.","zh-TW":"外部因素影響了公司的績效。"},{"en":"An external audit will be conducted.","zh-TW":"將進行外部審計。"}]', '{"adjective":"external","adverb":"externally"}', NULL, 3, 2647, 358),
(2648, 'external audit', '/ɪkˈstɜːrnəl ˈɔːdɪt/', 'noun', '{"zh-TW":["外部審計"],"en":["an independent review of financial statements by an external auditor"]}', NULL, 'conduct an external audit / pass external audit', '[{"en":"The external audit confirmed the accuracy of the financial statements.","zh-TW":"外部審計確認了財務報表的準確性。"},{"en":"Listed companies are required to undergo an annual external audit.","zh-TW":"上市公司必須接受年度外部審計。"}]', NULL, NULL, 5, 2648, NULL),
(2649, 'external financing', '/ɪkˈstɜːrnəl ˈfaɪnænsɪŋ/', 'noun', '{"zh-TW":["外部融資"],"en":["obtaining funds from outside the company through borrowing or equity"]}', NULL, 'seek external financing / external financing options', '[{"en":"The startup sought external financing to accelerate growth.","zh-TW":"新創公司尋求外部融資以加速增長。"},{"en":"External financing includes bank loans, bonds, and equity issuance.","zh-TW":"外部融資包括銀行貸款、債券和股本發行。"}]', NULL, NULL, 5, 2649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2650, 'externality', '/ˌekstɜːrˈnælɪti/', 'noun', '{"zh-TW":["外部性"],"en":["a cost or benefit affecting parties not directly involved in a transaction"]}', NULL, 'negative externality / positive externality / internalize externalities', '[{"en":"Carbon emissions are a negative externality not reflected in market prices.","zh-TW":"碳排放是市場價格中沒有反映的負外部性。"},{"en":"Governments use taxes and regulations to internalize negative externalities.","zh-TW":"政府使用稅收和監管來使負外部性內部化。"}]', '{"adjective":"external","adverb":"externally"}', NULL, 4, 2650, NULL),
(2651, 'extract', '/ɪkˈstrækt/', 'verb / noun', '{"zh-TW":["提取；摘錄"],"en":["to remove or obtain"]}', NULL, 'extract data/information', '[{"en":"We need to extract data from the system.","zh-TW":"我們需要從系統中提取數據。"},{"en":"The dentist extracted the tooth.","zh-TW":"牙醫拔了那顆牙。"}]', '{"noun":"extract/extraction","verb":"extract"}', NULL, 3, 2651, NULL),
(2652, 'extracurricular', '/ˌɛkstrəkəˈrɪkjʊlər/', 'adjective', '{"zh-TW":["課外的"],"en":["outside the regular academic curriculum"]}', NULL, 'extracurricular activity / extracurricular involvement', '[{"en":"Extracurricular activities help students develop leadership skills.","zh-TW":"課外活動幫助學生培養領導能力。"},{"en":"Colleges value extracurricular involvement in applicants.","zh-TW":"大學重視申請者的課外活動參與。"}]', NULL, NULL, 5, 2652, NULL),
(2653, 'extracurricular activity', '/''ekstrəkəˌrɪkjələr ækˌtɪvɪti/', 'noun', '{"zh-TW":["課外活動"],"en":["an activity that students participate in outside of normal school or college curriculum"]}', NULL, 'join an extracurricular activity / extracurricular activity benefit / offer extracurricular activities', '[{"en":"Extracurricular activities like debate club help students develop communication skills.","zh-TW":"課外活動如辯論俱樂部幫助學生發展溝通技能。"},{"en":"Colleges look for applicants who demonstrate leadership through extracurricular activities.","zh-TW":"大學尋找通過課外活動展示領導力的申請人。"}]', '{"adjective":"extracurricular"}', NULL, 5, 2653, NULL),
(2654, 'extraordinary', '/ɪkˈstrɔːrdəneri/', 'adjective', '{"zh-TW":["非凡的；特別的"],"en":["very unusual or remarkable"]}', NULL, 'extraordinary achievement/circumstances', '[{"en":"She showed extraordinary leadership.","zh-TW":"她展示了非凡的領導力。"},{"en":"Due to extraordinary circumstances, the event was cancelled.","zh-TW":"由於特殊情況，活動被取消了。"}]', '{"adjective":"extraordinary","adverb":"extraordinarily"}', NULL, 5, 2654, NULL),
(2655, 'extrapolate', '/ɪkˈstræpəleɪt/', 'verb', '{"zh-TW":["推斷；外推"],"en":["to extend conclusions beyond known data by inferring from trends"]}', NULL, 'extrapolate from data / extrapolate trends / extrapolate results', '[{"en":"We cannot safely extrapolate these results to a larger population.","zh-TW":"我們無法安全地將這些結果外推到更大的群體。"},{"en":"The analyst extrapolated future growth from current indicators.","zh-TW":"分析師從當前指標推斷出未來的增長。"}]', '{"noun":"extrapolation","adjective":"extrapolative"}', NULL, 4, 2655, NULL),
(2656, 'extrapolation', '/ɪkˌstræpəˈleɪʃən/', 'noun', '{"zh-TW":["推斷；外推"],"en":["the extension of a method or conclusion to an unknown situation"]}', NULL, 'cautious extrapolation / invalid extrapolation / data extrapolation', '[{"en":"The extrapolation from laboratory to real-world conditions requires caution.","zh-TW":"從實驗室到現實世界條件的推斷需要謹慎。"},{"en":"Extrapolation of short-term trends to long-term predictions is often unreliable.","zh-TW":"將短期趨勢外推至長期預測通常是不可靠的。"}]', '{"verb":"extrapolate","adjective":"extrapolative"}', NULL, 5, 2656, NULL),
(2657, 'extrinsic', '/''ekˌstrɪnsɪk/', 'adjective', '{"zh-TW":["外在的；外部的"],"en":["not part of the essential nature of someone or something; coming from outside"]}', NULL, 'extrinsic reward / extrinsic motivation / extrinsic factor', '[{"en":"Extrinsic rewards like bonuses can motivate employees in the short term.","zh-TW":"獎金等外在獎勵可以在短期內激勵員工。"},{"en":"Extrinsic factors such as weather affected the outcome of the outdoor event.","zh-TW":"天氣等外在因素影響了戶外活動的結果。"}]', '{"adverb":"extrinsically"}', NULL, 3, 2657, NULL),
(2658, 'eye', '/aɪ/', 'noun', '{"zh-TW":["【主要意義-名詞】眼睛","【次要意義-動詞】注視；盯著看；端詳","【次要意義-名詞】眼力；鑒賞力"],"en":["[primary - noun] the organ of sight","[secondary - verb] to look at someone or something carefully","[secondary - noun] a keen sense of judgment or appreciation"]}', NULL, 'eye someone suspiciously / an eye for detail / keep an eye on / eye-catching', '[{"en":"She eyed the new candidate carefully during the interview.","zh-TW":"她在面試過程中仔細打量這位新候選人。"},{"en":"The manager has a good eye for talent and has recruited several top performers.","zh-TW":"這位經理很有識才的眼力，已招募了幾位頂尖績效員工。"},{"en":"Please keep an eye on the inventory levels and report any shortage.","zh-TW":"請留意庫存水平，並報告任何短缺情況。"}]', '{"adjective":"eye-catching, eagle-eyed"}', '動詞 eye = 「端詳/注視」，片語 have an eye for（對……有眼光）、keep an eye on（留意/監視）、eye-catching（引人注目的）均是 TOEIC 職場描述常見用法。', 1, 2658, NULL),
(2659, 'fabricate', '/ˈfæbrɪkeɪt/', 'verb', '{"zh-TW":["捏造；製造"],"en":["to invent false information; to construct"]}', NULL, 'fabricate evidence/a story', '[{"en":"He was accused of fabricating evidence.","zh-TW":"他被指控捏造證據。"},{"en":"The parts are fabricated in our factory.","zh-TW":"零件在我們工廠製造。"}]', '{"noun":"fabrication","verb":"fabricate"}', NULL, 3, 2659, NULL),
(2660, 'face', '/feɪs/', 'verb / noun', '{"zh-TW":["【主要意義-名詞/動詞】臉；面對","【次要意義-動詞】朝向；面向（某方向）","【次要意義-名詞】表面；外觀；正面","【次要意義-名詞】面子；聲譽"],"en":["[primary] the front part of the head; to look toward","[secondary - verb] to be positioned toward a particular direction","[secondary - noun] the surface or front of something","[secondary - noun] reputation or social standing"]}', NULL, 'face value / at face value / face the consequences / save face / lose face', '[{"en":"Do not take the contract terms at face value; read the fine print.","zh-TW":"不要只看合約條款的表面意思，要仔細閱讀細則。"},{"en":"The company managed to save face by issuing a public apology.","zh-TW":"公司通過發表公開道歉來保住了顏面。"},{"en":"The new building faces the main commercial district.","zh-TW":"新大樓面朝主要商業區。"}]', '{"adjective":"face-to-face, facing","noun":"facade"}', 'face value（表面價值/票面價值）、save face（保住面子）、at face value（按表面意思）均是 TOEIC 商業和社交文章的常見陷阱，face 的金融含義（票面）也常見。', 1, 2660, NULL),
(2661, 'face value', '/feɪs ˈvæljuː/', 'noun', '{"zh-TW":["面值；票面價值"],"en":["the nominal or stated value of a financial instrument, such as a bond or share"]}', NULL, 'issued at face value / redeem at face value', '[{"en":"The bond was issued at face value of $1000 per note.","zh-TW":"債券以每張1,000元的票面價值發行。"},{"en":"The face value of a share may differ significantly from its market value.","zh-TW":"股票的面值可能與其市場價值大不相同。"}]', '{"synonym":"par value","synonym2":"nominal value"}', NULL, 4, 2661, NULL),
(2662, 'face-to-face meeting', '/ˌfeɪs tə ˈfeɪs ˈmiːtɪŋ/', 'noun', '{"zh-TW":["面對面會議"],"en":["a meeting conducted in person rather than remotely"]}', NULL, 'schedule a face-to-face meeting / prefer face-to-face meetings', '[{"en":"A face-to-face meeting was arranged to finalize the contract terms.","zh-TW":"安排了面對面會議以最終確定合約條款。"},{"en":"Face-to-face meetings are more effective for building client relationships.","zh-TW":"面對面會議在建立客戶關係方面更有效。"}]', NULL, NULL, 5, 2662, NULL),
(2663, 'facet', '/ˈfæsɪt/', 'noun', '{"zh-TW":["方面；層面"],"en":["one side of something many-sided; an aspect"]}', NULL, 'facet of a problem / multiple facets / every facet', '[{"en":"The study examines every facet of the regulatory environment.","zh-TW":"該研究審視了監管環境的每個方面。"},{"en":"His personality has many interesting facets.","zh-TW":"他的個性有許多有趣的方面。"}]', '{"adjective":"faceted"}', NULL, 2, 2663, NULL),
(2664, 'facilitate', '/fəˈsɪlɪteɪt/', 'verb', '{"zh-TW":["促進；使便利"],"en":["to make an action or process easier"]}', NULL, 'facilitate communication/growth', '[{"en":"Technology facilitates remote collaboration.","zh-TW":"技術促進了遠端協作。"},{"en":"The mediator facilitated the discussion.","zh-TW":"調解人促進了討論。"}]', '{"noun":"facilitation/facilitator","verb":"facilitate"}', NULL, 4, 2664, 684),
(2665, 'facilitate learning', '/''fəˌsɪlɪˌteɪt ˌlɜːrnɪŋ/', 'phrase', '{"zh-TW":["促進學習；便於學習"],"en":["to make the process of learning easier or more effective"]}', NULL, 'facilitate learning through technology / facilitate active learning / facilitate deeper learning', '[{"en":"Technology can greatly facilitate learning by providing access to diverse resources.","zh-TW":"技術可以通過提供多元資源的訪問大大促進學習。"},{"en":"Collaborative group work facilitates learning by exposing students to different perspectives.","zh-TW":"協作小組工作通過讓學生接觸不同的觀點來促進學習。"}]', '{"verb":"facilitate","noun":"facilitation"}', NULL, 5, 2665, NULL),
(2666, 'facilitated', '/fəˈsɪlɪteɪtɪd/', 'adjective', '{"zh-TW":["被便利化的；有助推的"],"en":["made easier or less difficult with assistance"]}', NULL, 'facilitated discussion / facilitated learning / facilitated process', '[{"en":"A facilitated workshop helped the team reach consensus quickly.","zh-TW":"一個有助推的研討會幫助團隊迅速達成共識。"},{"en":"Facilitated negotiation is often used in complex multi-party disputes.","zh-TW":"有助推的談判通常用於複雜的多方爭議。"}]', '{"verb":"facilitate","noun":"facilitation"}', NULL, 4, 2666, NULL),
(2667, 'facilitator', '/fəˈsɪlɪteɪtər/', 'noun', '{"zh-TW":["主持人；促進者"],"en":["a person who helps a group or process operate more effectively"]}', NULL, 'act as a facilitator / workshop facilitator', '[{"en":"The HR manager served as facilitator for the conflict resolution session.","zh-TW":"人力資源管理者擔任了衝突解決會議的主持人。"},{"en":"A skilled facilitator keeps discussions productive and on track.","zh-TW":"熟練的主持人使討論保持高效並按計劃進行。"}]', '{"verb":"facilitate","adjective":"facilitated"}', NULL, 4, 2667, NULL),
(2668, 'facilities', '/fəˈsɪlɪtiz/', 'noun', '{"zh-TW":["設施；設備"],"en":["equipment and services available at a place"]}', NULL, 'hotel facilities / use the facilities', '[{"en":"The hotel''s facilities include a gym and outdoor pool.","zh-TW":"飯店設施包括健身房和室外游泳池。"},{"en":"Conference facilities are available for business travelers.","zh-TW":"會議設施供商務旅客使用。"}]', '{"verb":"facilitate","adjective":"facilitated"}', NULL, 4, 2668, 359),
(2669, 'facilities management', '/fəˈsɪlɪtiz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["設施管理"],"en":["overseeing the physical workplace and related services"]}', NULL, 'facilities management team / outsource facilities management', '[{"en":"Facilities management ensures a safe and productive work environment.","zh-TW":"設施管理確保安全且有生產力的工作環境。"},{"en":"The facilities management team handled the office relocation.","zh-TW":"設施管理團隊處理了辦公室搬遷。"}]', '{"abbreviation":"FM","noun":"facilities manager"}', NULL, 5, 2669, NULL),
(2670, 'facility', '/fəˈsɪləti/', 'noun', '{"zh-TW":["設施；場所"],"en":["a building or place for a particular purpose"]}', NULL, 'manufacturing/training facility', '[{"en":"The company opened a new manufacturing facility.","zh-TW":"公司開設了新的生產設施。"},{"en":"Our facilities are available for conferences.","zh-TW":"我們的設施可供會議使用。"}]', '{"noun":"facility"}', NULL, 3, 2670, 31),
(2671, 'facility agreement', '/fəˈsɪlɪti əˈɡriːmənt/', 'noun', '{"zh-TW":["融資安排協議；信貸安排協議"],"en":["an agreement for a credit facility between a lender and borrower"]}', NULL, 'sign a facility agreement / facility agreement terms', '[{"en":"The facility agreement provided a 20 million revolving credit line.","zh-TW":"融資安排協議提供了2000萬元的循環信貸額度。"},{"en":"A facility agreement defines the borrowing limit, interest, and conditions.","zh-TW":"融資安排協議定義了借款限額、利息和條件。"}]', NULL, NULL, 5, 2671, NULL),
(2672, 'fact', '/fækt/', 'noun', '{"zh-TW":["事實"],"en":["something known to be true"]}', NULL, 'in fact / as a matter of fact', '[{"en":"In fact, sales increased by 20%.","zh-TW":"事實上，銷售增長了20%。"},{"en":"We need facts, not opinions.","zh-TW":"我們需要事實，不是意見。"}]', '{"noun":"fact","adjective":"factual","adverb":"factually"}', NULL, 1, 2672, NULL),
(2673, 'factor', '/ˈfæktər/', 'noun', '{"zh-TW":["因素；要素","因素"],"en":["a circumstance that contributes to a result"]}', '{"root":{"text":"fact","meaning":"make/do (做)"},"suffix":{"text":"-or","meaning":"that which (…的東西)"},"logic":"促成某事發生的東西，即「因素」。"}', 'key/determining factor; key factor / risk factor / contributing factor', '[{"en":"Cost is a major factor in the decision.","zh-TW":"成本是決策中的主要因素。"},{"en":"Several factors contributed to the failure.","zh-TW":"幾個因素導致了失敗。"},{"en":"Cost is an important factor in this decision.","zh-TW":"成本是這個決策中的重要因素。"},{"en":"Several factors contributed to the delay.","zh-TW":"多項因素導致了延遲。"}]', '{"noun":"factor","verb":"factor","adjective":"factorial"}', NULL, 2, 2673, 360),
(2674, 'factored receivables', '/ˈfæktərd rɪˈsiːvəblz/', 'noun', '{"zh-TW":["已保理應收帳款"],"en":["accounts receivable that have been sold to a factoring company for immediate cash"]}', NULL, 'sell factored receivables / factored receivables balance', '[{"en":"By using factored receivables, the company converted invoices to immediate cash.","zh-TW":"通過使用保理應收帳款，公司將發票轉換為即時現金。"},{"en":"Factored receivables reduce the book value of outstanding debtors.","zh-TW":"保理應收帳款減少了未付款客戶的帳面價值。"}]', NULL, NULL, 5, 2674, NULL),
(2675, 'factoring', '/ˈfæktərɪŋ/', 'noun', '{"zh-TW":["應收帳款融資；保理"],"en":["selling accounts receivable to a third party at a discount for immediate cash"]}', NULL, 'invoice factoring / factoring company / factoring facility', '[{"en":"Factoring provided the small business with immediate working capital.","zh-TW":"保理為小企業提供了即時營運資金。"},{"en":"The company used factoring to bridge the gap between invoicing and payment.","zh-TW":"公司使用保理來彌補開票和收款之間的差距。"}]', '{"verb":"factor","noun":"factor"}', NULL, 3, 2675, NULL),
(2676, 'faculty', '/ˈfækəlti/', 'noun', '{"zh-TW":["全體教職員；院系"],"en":["the teaching staff of a university"]}', NULL, 'faculty member / faculty meeting', '[{"en":"The faculty voted on the proposal.","zh-TW":"教職員對提案進行了投票。"},{"en":"She''s a faculty member in the science department.","zh-TW":"她是理學院的教職員。"}]', NULL, NULL, 3, 2676, NULL),
(2677, 'fail', '/feɪl/', 'verb', '{"zh-TW":["失敗；未能"],"en":["to be unsuccessful; to neglect"]}', NULL, 'fail to meet/deliver', '[{"en":"The project failed to meet its objectives.","zh-TW":"該項目未能達成目標。"},{"en":"The business failed within two years.","zh-TW":"這家企業在兩年內倒閉了。"}]', '{"noun":"failure","verb":"fail"}', NULL, 1, 2677, NULL),
(2678, 'failure', 'ˈfeɪljər', 'noun', '{"zh-TW":["失敗；失誤","故障"],"en":["a lack of success","a breakdown"]}', NULL, 'system failure/product failure', '[{"en":"We must analyze the causes of failure.","zh-TW":"我們必須分析失敗的原因。"}]', '{"verb":"fail","adjective":"failed","adverb":"failingly"}', NULL, 3, 2678, NULL),
(2679, 'fair', '/fer/', 'adjective / noun', '{"zh-TW":["公平的；展覽會"],"en":["treating people equally; a commercial exhibition"]}', NULL, 'fair price/trade fair', '[{"en":"We offer fair prices to all customers.","zh-TW":"我們對所有客戶提供公平的價格。"},{"en":"We met potential clients at the trade fair.","zh-TW":"我們在商展上認識了潛在客戶。"}]', '{"noun":"fairness","adjective":"fair","adverb":"fairly"}', NULL, 1, 2679, NULL),
(2680, 'fair competition', '/feər ˌkɒmpɪˈtɪʃən/', 'noun', '{"zh-TW":["公平競爭"],"en":["market conditions where no single company has an unfair advantage"]}', NULL, 'promote fair competition / ensure fair competition', '[{"en":"The regulator oversees markets to ensure fair competition.","zh-TW":"監管機構監督市場以確保公平競爭。"},{"en":"Fair competition benefits consumers through lower prices and better quality.","zh-TW":"公平競爭通過更低的價格和更好的品質使消費者受益。"}]', NULL, NULL, 5, 2680, NULL),
(2681, 'fair market value', '/feər ˈmɑːrkɪt ˈvæljuː/', 'noun', '{"zh-TW":["公平市場價值"],"en":["the price at which a willing buyer and seller would agree in a free market"]}', NULL, 'determine fair market value / transact at fair market value', '[{"en":"The property was sold at fair market value after an independent valuation.","zh-TW":"在獨立估值後，房產以公平市場價值出售了。"},{"en":"Tax authorities use fair market value to assess capital gains.","zh-TW":"稅務機關使用公平市場價值來評估資本利得。"}]', NULL, NULL, 5, 2681, NULL),
(2682, 'fair trade', '/feər treɪd/', 'noun', '{"zh-TW":["公平貿易"],"en":["trading practices ensuring producers receive fair pay and safe conditions"]}', NULL, 'support fair trade / fair trade certification', '[{"en":"The coffee was certified as fair trade by an independent body.","zh-TW":"咖啡被獨立機構認證為公平貿易產品。"},{"en":"Fair trade principles ensure workers in developing countries receive fair wages.","zh-TW":"公平貿易原則確保發展中國家的工人獲得公平薪資。"}]', NULL, NULL, 4, 2682, NULL),
(2683, 'fair value', '/feər ˈvæljuː/', 'noun', '{"zh-TW":["公平價值"],"en":["the estimated market value of an asset determined by agreed standards"]}', NULL, 'measure fair value / fair value accounting', '[{"en":"Under fair value accounting, assets are recorded at current market prices.","zh-TW":"在公平價值會計下，資產按當前市場價格記錄。"},{"en":"Fair value adjustments can cause significant income statement volatility.","zh-TW":"公平價值調整可能導致損益表的顯著波動。"}]', NULL, NULL, 4, 2683, NULL),
(2684, 'fall', '/fɔːl/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】落下；跌倒","【次要意義-名詞（美式）】秋天","【次要意義-名詞】瀑布（複數 falls）","【次要意義-動詞】淪為；變成某種狀態"],"en":["[primary] to drop or descend; the act of dropping","[secondary - noun (AmE)] autumn","[secondary - noun] a waterfall (often plural)","[secondary - verb] to enter or pass into a state"]}', NULL, 'fall due / fall short / fall into place / fall flat / Niagara Falls', '[{"en":"Sales figures fell short of the projected targets for the quarter.","zh-TW":"本季的銷售數字未達預期目標。"},{"en":"The payment falls due on the last business day of each month.","zh-TW":"款項在每月最後一個工作日到期。"},{"en":"The new marketing plan fell flat with focus groups.","zh-TW":"新的行銷計劃在焦點小組中未能引起反響。"}]', '{"noun":"downfall","adjective":"fallen"}', 'fall 有多個次要意義：fall short（未達到）、fall due（到期）、fall flat（失敗/未引起反響）均為 TOEIC 閱讀高頻商業用語，不可望文生義。', 1, 2684, NULL),
(2685, 'fallacy', '/ˈfæləsi/', 'noun', '{"zh-TW":["謬論；謬誤"],"en":["a mistaken belief or a failure in reasoning"]}', NULL, 'commit a fallacy / logical fallacy / common fallacy', '[{"en":"The argument contains a logical fallacy that undermines its conclusion.","zh-TW":"該論點包含一個邏輯謬誤，破壞了其結論。"},{"en":"It is a fallacy to assume that correlation implies causation.","zh-TW":"假設相關性意味著因果關係是一種謬論。"}]', '{"adjective":"fallacious","adverb":"fallaciously"}', NULL, 3, 2685, NULL),
(2686, 'false advertising', '/fɔːls ˈædvətaɪzɪŋ/', 'noun', '{"zh-TW":["虛假廣告"],"en":["advertising that makes misleading or false claims about products or services"]}', NULL, 'engage in false advertising / prosecuted for false advertising', '[{"en":"The company was fined for false advertising about product performance claims.","zh-TW":"公司因對產品性能聲明進行虛假廣告而被罰款。"},{"en":"False advertising damages consumer trust and invites regulatory action.","zh-TW":"虛假廣告損害了消費者信任並引發了監管行動。"}]', NULL, NULL, 5, 2686, NULL),
(2687, 'false consciousness', '/fɔːls ˈkɒnʃəsnəs/', 'noun', '{"zh-TW":["虛假意識"],"en":["a Marxist concept where workers internalize the ideology of the ruling class"]}', NULL, 'develop false consciousness / overcome false consciousness / false consciousness theory', '[{"en":"Marx argued that false consciousness prevents workers from recognizing their exploitation.","zh-TW":"馬克思認為虛假意識阻止工人認識到他們受到的剝削。"},{"en":"Critics use false consciousness to explain why people vote against their economic interests.","zh-TW":"批評者使用虛假意識來解釋為什麼人們投票反對自己的經濟利益。"}]', NULL, NULL, 5, 2687, NULL),
(2688, 'falsifiable', '/ˈfɔːlsɪfaɪəbəl/', 'adjective', '{"zh-TW":["可否證的；可驗偽的"],"en":["able to be proven false by observation or experiment"]}', NULL, 'falsifiable hypothesis / falsifiable claim / falsifiable theory', '[{"en":"Popper argued that scientific theories must be falsifiable.","zh-TW":"波普爾認為科學理論必須是可否證的。"},{"en":"A claim that cannot be falsified is metaphysical rather than scientific.","zh-TW":"不能被否證的主張是形而上學的而非科學的。"}]', '{"noun":"falsifiability","verb":"falsify"}', NULL, 4, 2688, NULL),
(2689, 'familiar', '/fəˈmɪliər/', 'adjective', '{"zh-TW":["熟悉的"],"en":["well known; often seen or experienced"]}', NULL, 'familiar with', '[{"en":"Are you familiar with this software?","zh-TW":"你熟悉這個軟體嗎？"},{"en":"The process should be familiar to all staff.","zh-TW":"所有員工應該熟悉這個流程。"}]', '{"noun":"familiarity","verb":"familiarize","adjective":"familiar"}', NULL, 3, 2689, NULL),
(2690, 'family', '/ˈfæməli/', 'noun', '{"zh-TW":["家庭；家族"],"en":["a group of related people","a group of related things"]}', NULL, 'family business / family-friendly', '[{"en":"It is a family-owned business.","zh-TW":"這是一家家族企業。"},{"en":"The company offers family-friendly policies.","zh-TW":"公司提供家庭友善政策。"}]', '{"noun":"family","adjective":"familiar","noun2":"familiarity"}', NULL, 2, 2690, NULL),
(2691, 'family medicine', '/ˈfæmɪli ˈmɛdɪsɪn/', 'noun', '{"zh-TW":["家庭醫學；家庭醫療"],"en":["medical care provided to patients of all ages by a generalist"]}', NULL, 'family medicine clinic / practice family medicine', '[{"en":"Her family medicine doctor handles all routine health issues.","zh-TW":"她的家庭醫學醫生處理所有例行健康問題。"},{"en":"Family medicine emphasizes preventive care and long-term relationships.","zh-TW":"家庭醫學強調預防護理和長期醫患關係。"}]', NULL, NULL, 5, 2691, NULL),
(2692, 'famous', 'ˈfeɪməs', 'adjective', '{"zh-TW":["著名的；有名的","出名的"],"en":["known by many people","well-known"]}', NULL, 'famous brand/world-famous', '[{"en":"The company is famous for its innovation.","zh-TW":"該公司以其創新而聞名。"}]', '{"noun":"fame","adverb":"famously"}', NULL, 2, 2692, NULL),
(2693, 'fan', '/fæn/', 'noun', '{"zh-TW":["粉絲；風扇"],"en":["a person who admires someone or something"]}', NULL, 'fan base / big fan', '[{"en":"I''m a big fan of this band.","zh-TW":"我是這個樂隊的忠實粉絲。"},{"en":"Turn on the fan, it''s hot.","zh-TW":"開風扇，好熱。"}]', NULL, NULL, 1, 2693, NULL),
(2694, 'far', '/fɑːr/', 'adverb', '{"zh-TW":["遠；遠遠地"],"en":["at a great distance","to a great degree"]}', NULL, 'so far / by far', '[{"en":"So far, everything is going well.","zh-TW":"到目前為止，一切順利。"},{"en":"This is by far the best option.","zh-TW":"這無疑是最好的選擇。"}]', '{"adverb":"far","adjective":"far","adjective2":"farther"}', NULL, 1, 2694, NULL),
(2695, 'far-reaching', '/''fɑːr ˌriːtʃɪŋ/', 'adjective', '{"zh-TW":["深遠的；廣泛影響的"],"en":["having wide-ranging effects or influence; extensive in scope"]}', NULL, 'far-reaching implications / far-reaching consequences / far-reaching reforms', '[{"en":"The government''s far-reaching economic reforms transformed the country''s financial system.","zh-TW":"政府深遠的經濟改革改造了該國的金融體系。"},{"en":"The technological advance had far-reaching implications for every sector of society.","zh-TW":"這項技術進步對社會各個部門都有深遠影響。"}]', NULL, NULL, 4, 2695, NULL),
(2696, 'fare', '/fer/', 'noun', '{"zh-TW":["票價；費用"],"en":["the money paid for a journey"]}', NULL, 'bus/air fare', '[{"en":"Air fares have increased significantly.","zh-TW":"機票價格大幅上漲。"},{"en":"What is the fare to the airport?","zh-TW":"到機場的票價是多少？"}]', '{"noun":"fare"}', NULL, 1, 2696, NULL),
(2697, 'fashion', '/ˈfæʃən/', 'noun', '{"zh-TW":["時尚；方式"],"en":["a popular trend; a manner of doing something"]}', NULL, 'in a timely fashion', '[{"en":"The fashion industry is worth billions.","zh-TW":"時尚產業價值數十億。"},{"en":"The work was completed in a professional fashion.","zh-TW":"工作以專業方式完成。"}]', '{"noun":"fashion","adjective":"fashionable"}', NULL, 3, 2697, NULL),
(2698, 'fast', '/fæst/', 'adjective', '{"zh-TW":["【主要意義-形容詞/副詞】快速的；快速地","【次要意義-名詞】齋戒；禁食期間","【次要意義-動詞】齋戒；禁食","【次要意義-形容詞】牢固的；緊緊的"],"en":["[primary] moving quickly; at high speed","[secondary - noun] a period of not eating for religious or health reasons","[secondary - verb] to abstain from food","[secondary - adjective] firmly fixed; secure"]}', NULL, 'break a fast / fast for a day / hold fast / fast asleep', '[{"en":"Employees observed a religious fast during the holiday period.","zh-TW":"員工在假期期間遵守宗教齋戒。"},{"en":"He decided to fast for 24 hours as part of the charity event.","zh-TW":"他決定禁食24小時以參與慈善活動。"},{"en":"The boat was held fast to the dock by two thick ropes.","zh-TW":"船被兩條粗繩牢牢地固定在碼頭上。"}]', '{"noun":"fasting","adjective":"fasting"}', 'fast 作名詞/動詞表「齋戒/禁食」，作形容詞表「固定的/牢固的」（如 fast asleep），這些用法在 TOEIC 文化或健康主題文章中偶爾出現。', 1, 2698, NULL),
(2699, 'fast food', '/fɑːst fuːd/', 'noun', '{"zh-TW":["速食；快餐"],"en":["food that is prepared and served quickly"]}', NULL, 'fast food restaurant / fast food chain', '[{"en":"Many travelers rely on fast food during long trips.","zh-TW":"許多旅行者在長途旅行中依賴速食。"},{"en":"Fast food chains are found in every major airport.","zh-TW":"每個主要機場都有速食連鎖店。"}]', NULL, NULL, 3, 2699, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2700, 'fast track', '/''fɑːst træk/', 'noun', '{"zh-TW":["快速通道；優先通道"],"en":["a route or method that allows faster passage, as through security or customs"]}', NULL, 'fast track lane / use the fast track / fast track program', '[{"en":"Premium passengers can use the fast track lane at security checkpoints.","zh-TW":"高端乘客可以在安全檢查站使用快速通道。"},{"en":"The fast track visa program allows approved applicants to enter within 24 hours.","zh-TW":"快速簽證計畫允許獲批准的申請人在24小時內入境。"}]', NULL, NULL, 4, 2700, NULL),
(2701, 'fast-moving consumer goods', '/fæst ˈmuːvɪŋ kənˈsjuːmər ɡʊdz/', 'noun', '{"zh-TW":["快速消費品"],"en":["products with high turnover sold at relatively low cost"]}', NULL, 'market fast-moving consumer goods / FMCG sector', '[{"en":"The FMCG sector relies on high volumes and efficient distribution.","zh-TW":"快速消費品行業依賴於高產量和高效配送。"},{"en":"Fast-moving consumer goods require strong shelf presence in retail stores.","zh-TW":"快速消費品需要在零售店中有強大的貨架存在感。"}]', '{"abbreviation":"FMCG"}', NULL, 5, 2701, NULL),
(2702, 'fasting', '/''fɑːstɪŋ/', 'noun', '{"zh-TW":["禁食；斷食"],"en":["the practice of going without food or drink for a period of time, often for health or religious reasons"]}', NULL, 'intermittent fasting / practice fasting / fasting period', '[{"en":"Intermittent fasting involves cycling between periods of eating and fasting.","zh-TW":"間歇性禁食涉及在進食和禁食期之間循環。"},{"en":"Research suggests that short-term fasting may have several metabolic benefits.","zh-TW":"研究表明，短期禁食可能有幾種代謝益處。"}]', '{"verb":"fast","adjective":"fasting"}', NULL, 3, 2702, NULL),
(2703, 'fatal', '/ˈfeɪtəl/', 'adjective', '{"zh-TW":["致命的；嚴重的"],"en":["causing death; leading to failure"]}', NULL, 'fatal error/accident', '[{"en":"The software had a fatal error.","zh-TW":"軟體出現了致命錯誤。"},{"en":"The accident proved to be fatal.","zh-TW":"事故被證明是致命的。"}]', '{"noun":"fatality","adjective":"fatal","adverb":"fatally"}', NULL, 2, 2703, NULL),
(2704, 'father', '/ˈfɑːðər/', 'noun', '{"zh-TW":["父親"],"en":["a male parent"]}', NULL, 'founding father / father figure', '[{"en":"He is considered the founding father of the company.","zh-TW":"他被視為公司的創始人。"},{"en":"My father works in banking.","zh-TW":"我的父親在銀行業工作。"}]', '{"noun":"father","adjective":"fatherly","noun2":"fatherhood"}', NULL, 2, 2704, NULL),
(2705, 'fault', '/fɔːlt/', 'noun', '{"zh-TW":["過失；缺陷"],"en":["responsibility for a mistake; a defect"]}', NULL, 'at fault / find fault with', '[{"en":"The delay was not our fault.","zh-TW":"延誤不是我們的過失。"},{"en":"A fault was found in the equipment.","zh-TW":"在設備中發現了缺陷。"}]', '{"noun":"fault","adjective":"faulty"}', NULL, 2, 2705, NULL),
(2706, 'fault tolerance', '/fɔːlt ˈtɒlərəns/', 'noun', '{"zh-TW":["容錯性；容錯能力"],"en":["the ability of a system to continue operating despite failures"]}', NULL, 'build fault tolerance / fault tolerance mechanism / improve fault tolerance', '[{"en":"The distributed database was designed with fault tolerance as a key requirement.","zh-TW":"分散式資料庫的設計將容錯性作為關鍵需求。"},{"en":"RAID systems provide fault tolerance by replicating data across drives.","zh-TW":"RAID系統通過跨驅動器複製數據提供容錯能力。"}]', '{"adjective":"fault-tolerant"}', NULL, 5, 2706, NULL),
(2707, 'favor', '/ˈfeɪvər/', 'noun / verb', '{"zh-TW":["偏好；支持"],"en":["approval or support; to prefer"]}', NULL, 'in favor of', '[{"en":"The board voted in favor of the merger.","zh-TW":"董事會投票支持合併。"},{"en":"Most customers favor online shopping.","zh-TW":"大多數客戶偏好網上購物。"}]', '{"noun":"favor","verb":"favor","adjective":"favorable/favorite"}', NULL, 2, 2707, NULL),
(2708, 'fax', '/fæks/', 'noun', '{"zh-TW":["傳真"],"en":["a system for transmitting documents electronically over phone lines"]}', NULL, 'send a fax / fax machine', '[{"en":"Please fax the signed contract to our office.","zh-TW":"請將已簽署的合約傳真至我們的辦公室。"},{"en":"The fax number is listed on our website.","zh-TW":"傳真號碼列在我們的網站上。"}]', '{"verb":"fax","adjective":"faxed"}', NULL, 1, 2708, NULL),
(2709, 'fear', '/fɪr/', 'noun', '{"zh-TW":["恐懼；擔心"],"en":["an unpleasant emotion caused by danger"]}', NULL, 'for fear of / overcome fear', '[{"en":"She quit for fear of being laid off.","zh-TW":"她因害怕被裁員而辭職。"},{"en":"Overcome your fear of public speaking.","zh-TW":"克服你對公開演講的恐懼。"}]', '{"noun":"fear","verb":"fear","adjective":"fearful","adjective2":"fearless"}', NULL, 1, 2709, NULL),
(2710, 'feasibility', '/ˌfiːzəˈbɪlɪti/', 'noun', '{"zh-TW":["可行性"],"en":["the likelihood of a plan succeeding"]}', NULL, 'feasibility study / assess feasibility', '[{"en":"A feasibility study was conducted before launching the project.","zh-TW":"在啟動項目之前進行了可行性研究。"},{"en":"The report assessed the feasibility of building a new factory.","zh-TW":"報告評估了建設新工廠的可行性。"}]', '{"adjective":"feasible","adverb":"feasibly"}', NULL, 4, 2710, 786),
(2711, 'feasibility report', '/ˌfiːzəˈbɪlɪti rɪˈpɔːrt/', 'noun', '{"zh-TW":["可行性報告"],"en":["a document evaluating whether a project is viable"]}', NULL, 'prepare a feasibility report / submit a feasibility report', '[{"en":"The feasibility report recommended proceeding with the expansion.","zh-TW":"可行性報告建議繼續推進擴張計劃。"},{"en":"A feasibility report must consider technical, financial, and market factors.","zh-TW":"可行性報告必須考慮技術、財務和市場因素。"}]', NULL, NULL, 5, 2711, NULL),
(2712, 'feasibility study', '/ˌfiːzəˈbɪlɪti ˈstʌdi/', 'noun', '{"zh-TW":["可行性研究"],"en":["an analysis assessing whether a proposed project is practical and viable"]}', NULL, 'conduct a feasibility study / feasibility study report', '[{"en":"A feasibility study was conducted before committing to the new plant.","zh-TW":"在承諾建設新廠前進行了可行性研究。"},{"en":"The feasibility study determined the project was financially viable.","zh-TW":"可行性研究確定該項目在財務上是可行的。"}]', '{"adjective":"feasible","noun":"feasibility"}', NULL, 5, 2712, NULL),
(2713, 'feasible', '/ˈfiːzəbəl/', 'adjective', '{"zh-TW":["可行的"],"en":["possible and practical to do"]}', NULL, 'financially/technically feasible', '[{"en":"Is the plan financially feasible?","zh-TW":"這個計畫在財務上可行嗎？"},{"en":"We need to determine if the project is feasible.","zh-TW":"我們需要確定項目是否可行。"}]', '{"noun":"feasibility","adjective":"feasible"}', NULL, 3, 2713, 966),
(2714, 'feature', '/ˈfiːtʃər/', 'noun / verb', '{"zh-TW":["【主要意義-名詞】特徵；特色；功能","【次要意義-動詞】以……為主角；重點介紹；包含（作為特色）","【次要意義-名詞】（報紙/雜誌）特寫文章；專題報導"],"en":["[primary - noun] a distinctive quality or aspect of something","[secondary - verb] to include someone or something as an important part","[secondary - noun] a long article or program about a specific topic"]}', NULL, 'feature article / feature film / feature prominently / as a key feature', '[{"en":"The new product features an advanced noise-canceling system.","zh-TW":"新產品以先進的降噪系統為特色。"},{"en":"The brochure features our best-selling products from the past year.","zh-TW":"宣傳冊重點介紹了我們過去一年的暢銷產品。"},{"en":"A feature on sustainable packaging will appear in the next issue.","zh-TW":"關於可持續包裝的特寫文章將出現在下一期。"}]', '{"adjective":"featured"}', '動詞 feature = 「以……為特色/重點介紹」，名詞 feature = 「特寫報導/專題文章」，均是 TOEIC 廣告和媒體文章的常見用法，考生容易只記住名詞「特徵/功能」的意思。', 3, 2714, 361),
(2715, 'feature engineering', '/ˈfiːtʃər ˌendʒɪˈnɪərɪŋ/', 'noun', '{"zh-TW":["特徵工程"],"en":["the process of using domain knowledge to create features for machine learning models"]}', NULL, 'perform feature engineering / feature engineering pipeline / automated feature engineering', '[{"en":"Feature engineering often determines the success of a machine learning model.","zh-TW":"特徵工程通常決定了機器學習模型的成功。"},{"en":"Good feature engineering requires both technical and domain expertise.","zh-TW":"良好的特徵工程需要技術和領域專業知識。"}]', NULL, NULL, 5, 2715, NULL),
(2716, 'federal', '/ˈfedərəl/', 'adjective', '{"zh-TW":["聯邦的"],"en":["relating to a central government","relating to the national government"]}', NULL, 'federal government/law; federal government / federal law', '[{"en":"The federal government announced new regulations.","zh-TW":"聯邦政府宣布了新法規。"},{"en":"Federal taxes apply to all states.","zh-TW":"聯邦稅適用於所有州。"},{"en":"It''s a federal offense.","zh-TW":"這是聯邦罪行。"},{"en":"The federal government announced new policies.","zh-TW":"聯邦政府宣布了新政策。"}]', '{"noun":"federation","adjective":"federal"}', NULL, 3, 2716, NULL),
(2717, 'fee', '/fiː/', 'noun', '{"zh-TW":["費用；手續費"],"en":["a payment made for professional services"]}', NULL, 'annual/membership fee', '[{"en":"There is a monthly membership fee of $50.","zh-TW":"每月會費為50美元。"},{"en":"Legal fees can be expensive.","zh-TW":"法律費用可能很昂貴。"}]', '{"noun":"fee"}', NULL, 1, 2717, NULL),
(2718, 'fee schedule', '/fiː ˈʃedjuːl/', 'noun', '{"zh-TW":["費用明細表；收費表"],"en":["a document listing the fees charged for specific services"]}', NULL, 'publish a fee schedule / review the fee schedule', '[{"en":"Clients can review the fee schedule before engaging services.","zh-TW":"客戶可在使用服務前查看費用明細表。"},{"en":"The fee schedule was revised to reflect increased operating costs.","zh-TW":"費用明細表經修訂以反映增加的運營成本。"}]', NULL, NULL, 4, 2718, NULL),
(2719, 'fee structure', '/fiː ˈstrʌktʃər/', 'noun', '{"zh-TW":["費用結構"],"en":["the framework defining what fees are charged and under what conditions"]}', NULL, 'review the fee structure / fee structure transparency', '[{"en":"The consultant explained the fee structure before engagement began.","zh-TW":"顧問在開始工作前解釋了費用結構。"},{"en":"A transparent fee structure builds trust with clients.","zh-TW":"透明的費用結構建立了與客戶的信任。"}]', NULL, NULL, 5, 2719, NULL),
(2720, 'feedback', '/ˈfiːdbæk/', 'noun', '{"zh-TW":["反饋；回饋"],"en":["information about reactions to a product or performance"]}', NULL, 'provide/give feedback', '[{"en":"We appreciate your feedback on our service.","zh-TW":"我們感謝您對我們服務的反饋。"},{"en":"The manager gave constructive feedback.","zh-TW":"經理給予了建設性的反饋。"}]', '{"noun":"feedback"}', NULL, 3, 2720, 362),
(2721, 'feedback loop', '/ˈfiːdbæk luːp/', 'noun', '{"zh-TW":["反饋循環"],"en":["a process where outputs are fed back as inputs to improve a system"]}', NULL, 'create a feedback loop / close the feedback loop / continuous feedback loop', '[{"en":"A feedback loop between sales and product improved feature development.","zh-TW":"銷售和產品之間的反饋循環改善了功能開發。"},{"en":"Customer feedback loops help companies continuously improve their services.","zh-TW":"客戶反饋循環幫助公司持續改善其服務。"}]', NULL, NULL, 5, 2721, NULL),
(2722, 'feedback mechanism', '/''fiːdbæk ˌmekənɪzəm/', 'noun', '{"zh-TW":["反饋機制"],"en":["a system through which information about performance or quality is returned to the appropriate party for improvement"]}', NULL, 'establish a feedback mechanism / feedback mechanism improvement / use a feedback mechanism', '[{"en":"The company implemented a feedback mechanism to collect employee suggestions.","zh-TW":"公司建立了一個反饋機制，收集員工建議。"},{"en":"A good feedback mechanism ensures that customer complaints lead to real improvements.","zh-TW":"一個好的反饋機制確保客戶投訴能帶來真正的改進。"}]', NULL, NULL, 5, 2722, NULL),
(2723, 'feel', '/fiːl/', 'verb', '{"zh-TW":["感覺；覺得"],"en":["to experience an emotion","to be aware of through touch"]}', NULL, 'feel free / feel like', '[{"en":"Feel free to ask any questions.","zh-TW":"請隨時提問。"},{"en":"I feel confident about this decision.","zh-TW":"我對這個決定感到有信心。"}]', '{"verb":"feel","noun":"feeling"}', NULL, 1, 2723, NULL),
(2724, 'feeling', 'ˈfiːlɪŋ', 'noun', '{"zh-TW":["感覺；情感","感受"],"en":["an emotion or sentiment","a physical sensation"]}', NULL, 'gut feeling/mixed feelings', '[{"en":"I have a good feeling about this deal.","zh-TW":"我對這筆交易有好的感覺。"}]', '{"verb":"feel","adjective":"feeling"}', NULL, 3, 2724, NULL),
(2725, 'fellowship', '/ˈfɛloʊʃɪp/', 'noun', '{"zh-TW":["獎學金；研究員資格"],"en":["money given for academic study; companionship"]}', NULL, 'research fellowship / fellowship program', '[{"en":"He received a research fellowship.","zh-TW":"他獲得了研究獎學金。"},{"en":"The fellowship covers tuition and living expenses.","zh-TW":"該獎學金包含學費和生活費。"}]', NULL, NULL, 4, 2725, NULL),
(2726, 'felony', '/ˈfɛləni/', 'noun', '{"zh-TW":["重罪"],"en":["a serious crime"]}', NULL, 'commit a felony / felony charge', '[{"en":"Murder is classified as a felony.","zh-TW":"謀殺被歸類為重罪。"},{"en":"He was charged with a felony.","zh-TW":"他被指控犯了重罪。"}]', NULL, NULL, 2, 2726, NULL),
(2727, 'feminist theory', '/ˈfemɪnɪst ˈθɪəri/', 'noun', '{"zh-TW":["女性主義理論"],"en":["frameworks analyzing gender inequality and promoting gender justice"]}', NULL, 'second-wave feminist theory / intersectional feminist theory / apply feminist theory', '[{"en":"Feminist theory examines how patriarchy operates in law, culture, and daily life.","zh-TW":"女性主義理論研究父權制如何在法律、文化和日常生活中運作。"},{"en":"Liberal feminist theory focuses on achieving equality through legal reform.","zh-TW":"自由主義女性主義理論聚焦於通過法律改革實現平等。"}]', NULL, NULL, 5, 2727, NULL),
(2728, 'fermentation', '/''fɜːrmenˈteɪʃən/', 'noun', '{"zh-TW":["發酵"],"en":["a metabolic process in which microorganisms convert sugar into acids, gases, or alcohol"]}', NULL, 'natural fermentation / lactic fermentation / fermentation process', '[{"en":"Fermentation is used to make bread, yogurt, and wine.","zh-TW":"發酵用於製作麵包、優格和葡萄酒。"},{"en":"The unique flavor of sourdough bread comes from the fermentation of wild yeast.","zh-TW":"酸麵包獨特的風味來自野生酵母的發酵。"}]', '{"verb":"ferment","adjective":"fermented"}', NULL, 4, 2728, NULL),
(2729, 'fermented', '/''fɜːrmentɪd/', 'adjective', '{"zh-TW":["發酵的"],"en":["having undergone fermentation; made through microbial activity"]}', NULL, 'fermented food / fermented drink / naturally fermented', '[{"en":"Fermented foods like kimchi and yogurt are beneficial for gut health.","zh-TW":"像泡菜和優格這樣的發酵食品對腸道健康有益。"},{"en":"Many traditional cuisines feature fermented ingredients for depth of flavor.","zh-TW":"許多傳統菜系都以發酵食材為特色，以增添風味深度。"}]', '{"noun":"fermentation"}', NULL, 3, 2729, NULL),
(2730, 'fermented drink', '/''fɜːrmentɪd drɪŋk/', 'noun', '{"zh-TW":["發酵飲料"],"en":["a beverage produced through the fermentation of sugars by yeast or bacteria"]}', NULL, 'traditional fermented drink / popular fermented drink / health benefits of fermented drinks', '[{"en":"Kombucha is a popular fermented drink known for its probiotic benefits.","zh-TW":"康普茶是一種以益生菌功效著稱的流行發酵飲料。"},{"en":"Kefir is a fermented drink made from milk and has a tangy, yogurt-like taste.","zh-TW":"克菲爾是一種由牛奶製成的發酵飲料，具有酸奶般的濃郁口感。"}]', NULL, NULL, 5, 2730, NULL),
(2731, 'fermented food', '/''fɜːrmentɪd fuːd/', 'noun', '{"zh-TW":["發酵食品"],"en":["food that has been preserved or transformed through fermentation by microorganisms"]}', NULL, 'eat fermented food / traditional fermented food / health benefits of fermented food', '[{"en":"Fermented foods like miso and sauerkraut have been part of human diets for centuries.","zh-TW":"像味噌和酸菜這樣的發酵食品已經是人類飲食的一部分長達幾個世紀。"},{"en":"The growing interest in gut health has boosted sales of fermented foods.","zh-TW":"對腸道健康的日益關注推動了發酵食品的銷售增長。"}]', NULL, NULL, 5, 2731, NULL),
(2732, 'ferry', '/''feri/', 'noun', '{"zh-TW":["渡輪；渡船"],"en":["a boat or ship for conveying passengers and goods, especially across a body of water"]}', NULL, 'catch a ferry / ferry terminal / take a ferry', '[{"en":"We took the ferry from the mainland to the island.","zh-TW":"我們乘渡輪從大陸到達島嶼。"},{"en":"The ferry crossing takes about forty-five minutes in calm weather.","zh-TW":"在平靜的天氣中，渡輪過海需要大約四十五分鐘。"}]', NULL, NULL, 2, 2732, NULL),
(2733, 'few', '/fjuː/', 'adjective', '{"zh-TW":["少數的；幾個"],"en":["a small number of"]}', NULL, 'a few / quite a few', '[{"en":"A few candidates were shortlisted.","zh-TW":"幾位候選人進入了決選名單。"},{"en":"Quite a few people attended.","zh-TW":"相當多人出席了。"}]', '{"adjective":"few","adjective2":"fewer","adjective3":"fewest"}', NULL, 1, 2733, NULL),
(2734, 'fiat', '/ˈfiːæt/', 'noun', '{"zh-TW":["命令；法令；法定"],"en":["an authoritative decree; currency backed by government authority rather than a commodity"]}', NULL, 'fiat money / government fiat / fiat currency', '[{"en":"Most modern currencies are fiat money not backed by gold or silver.","zh-TW":"大多數現代貨幣是不以黃金或白銀為後盾的法定貨幣。"},{"en":"The regulation was implemented by executive fiat rather than legislation.","zh-TW":"該法規是通過行政命令而非立法來實施的。"}]', NULL, NULL, 1, 2734, NULL),
(2735, 'fiber', '/''faɪbər/', 'noun', '{"zh-TW":["纖維素；膳食纖維"],"en":["a dietary component found in plant foods that aids digestion"]}', NULL, 'dietary fiber / high-fiber diet / fiber intake', '[{"en":"A diet high in fiber helps prevent digestive problems.","zh-TW":"高纖維飲食有助於預防消化問題。"},{"en":"Fruits, vegetables, and whole grains are excellent sources of dietary fiber.","zh-TW":"水果、蔬菜和全穀類是膳食纖維的絕佳來源。"}]', '{"adjective":"fiber-rich"}', NULL, 2, 2735, NULL),
(2736, 'fiduciary', '/fɪˈdjuːʃəri/', 'adjective', '{"zh-TW":["信託的；受託的"],"en":["involving the legal duty to act in another''s best interest"]}', NULL, 'fiduciary duty / fiduciary responsibility', '[{"en":"Trustees have a fiduciary duty to act in beneficiaries'' interests.","zh-TW":"受託人有法律義務以受益人的利益行事。"},{"en":"A fiduciary relationship requires the highest standard of care.","zh-TW":"信託關係要求最高標準的謹慎義務。"}]', '{"noun":"fiduciary"}', NULL, 3, 2736, NULL),
(2737, 'fiduciary duty', '/fɪˈdjuːʃɪeri ˈdjuːti/', 'noun', '{"zh-TW":["受託義務；信義義務"],"en":["the legal obligation of a person to act in the best interest of another party"]}', NULL, 'fulfill fiduciary duty / fiduciary duty to shareholders', '[{"en":"Directors owe a fiduciary duty to act in the best interest of shareholders.","zh-TW":"董事對股東負有以其最佳利益行事的受託義務。"},{"en":"Breaching fiduciary duty can lead to personal liability for executives.","zh-TW":"違反受託義務可能導致高管承擔個人責任。"}]', NULL, NULL, 5, 2737, NULL),
(2738, 'field', '/fiːld/', 'noun', '{"zh-TW":["【主要意義-名詞】田野；領域；專業範疇","【次要意義-動詞】處理；回應（問題/投訴）","【次要意義-動詞】派遣（球員/團隊）上場"],"en":["[primary - noun] an open area of land; an area of study or work","[secondary - verb] to deal with a question, complaint, or inquiry","[secondary - verb] to send out a team or person to deal with something"]}', NULL, 'field questions / field complaints / field a team / field of expertise', '[{"en":"The customer service team fielded over 200 calls on the first day of the sale.","zh-TW":"客服團隊在促銷活動第一天接聽了逾200通電話。"},{"en":"The spokesperson fielded difficult questions from reporters after the conference.","zh-TW":"發言人在記者招待會後處理了記者提出的棘手問題。"},{"en":"She is an expert in her field and consulted by major corporations.","zh-TW":"她是她所在領域的專家，被各大企業諮詢。"}]', '{"noun":"fieldwork"}', '動詞 field questions/calls/complaints = 「接聽/處理（詢問/投訴）」，是 TOEIC 客服和公關文章的常見用法，考生容易只認識名詞「田野/領域」的意思。', 2, 2738, NULL),
(2739, 'field trip', '/''fiːld trɪp/', 'noun', '{"zh-TW":["校外教學；實地參觀"],"en":["a trip organized by a school or college to a place of educational interest"]}', NULL, 'organize a field trip / go on a field trip / field trip permission slip', '[{"en":"The biology class went on a field trip to the nature reserve to study local wildlife.","zh-TW":"生物課前往自然保護區進行校外教學，研究當地野生動物。"},{"en":"Field trips make learning more memorable by connecting classroom knowledge to the real world.","zh-TW":"校外教學通過將課堂知識與現實世界聯繫起來，使學習更加難忘。"}]', NULL, NULL, 4, 2739, NULL),
(2740, 'fight', '/faɪt/', 'verb', '{"zh-TW":["戰鬥；奮鬥"],"en":["to struggle against","to try hard to achieve"]}', NULL, 'fight for / fight against', '[{"en":"We must fight for our market share.","zh-TW":"我們必須為市場份額而戰。"},{"en":"They fought against the unfair regulation.","zh-TW":"他們反對不公平的法規。"}]', '{"verb":"fight","noun":"fight","noun2":"fighter"}', NULL, 2, 2740, NULL),
(2741, 'figure', '/ˈfɪɡjər/', 'noun / verb', '{"zh-TW":["數字；認為"],"en":["a number or amount; to think or calculate"]}', NULL, 'sales/profit figures', '[{"en":"Sales figures exceeded projections.","zh-TW":"銷售數字超出了預測。"},{"en":"We need to figure out the best approach.","zh-TW":"我們需要想出最佳方法。"}]', '{"noun":"figure","verb":"figure"}', NULL, 2, 2741, NULL),
(2742, 'file', '/faɪl/', 'noun / verb', '{"zh-TW":["檔案；提交"],"en":["a collection of data; to submit officially"]}', NULL, 'file a report/complaint', '[{"en":"Please file the documents in order.","zh-TW":"請按順序歸檔文件。"},{"en":"She filed a complaint with HR.","zh-TW":"她向人資部門提出了投訴。"}]', '{"noun":"file","verb":"file"}', NULL, 1, 2742, NULL),
(2743, 'file a complaint', '/faɪl ə kəmˈpleɪnt/', 'verb', '{"zh-TW":["提出投訴；提交投訴"],"en":["to submit a formal record of dissatisfaction to the appropriate authority"]}', NULL, 'file a complaint with the regulator / file an official complaint', '[{"en":"The customer filed a complaint with the consumer protection agency.","zh-TW":"客戶向消費者保護機構提出了投訴。"},{"en":"Filing a complaint triggers a formal investigation process.","zh-TW":"提出投訴觸發了正式調查流程。"}]', NULL, NULL, 5, 2743, NULL),
(2744, 'filing', '/ˈfaɪlɪŋ/', 'noun', '{"zh-TW":["歸檔；存檔"],"en":["the organizing and storing of documents"]}', NULL, 'document filing / filing system', '[{"en":"Maintain an organized filing system for all records.","zh-TW":"為所有記錄維護有組織的歸檔系統。"},{"en":"The filing of tax documents must be completed by March.","zh-TW":"稅務文件的歸檔必須在三月前完成。"}]', '{"verb":"file","noun":"file","adjective":"filed"}', NULL, 2, 2744, NULL),
(2745, 'fill', '/fɪl/', 'verb', '{"zh-TW":["填寫；填充"],"en":["to make full; to complete a form"]}', NULL, 'fill in/out a form', '[{"en":"Please fill out this application form.","zh-TW":"請填寫此申請表。"},{"en":"The position has been filled.","zh-TW":"該職位已被填補。"}]', '{"noun":"filling","verb":"fill"}', NULL, 1, 2745, NULL),
(2746, 'film', '/fɪlm/', 'noun', '{"zh-TW":["電影；影片"],"en":["a movie","a thin layer"]}', NULL, 'film industry / short film', '[{"en":"The film industry employs thousands.","zh-TW":"電影產業雇用了數千人。"},{"en":"We made a short promotional film.","zh-TW":"我們製作了一部短宣傳影片。"}]', '{"noun":"film","verb":"film","noun2":"filmmaker","noun3":"filming"}', NULL, 1, 2746, NULL),
(2747, 'final', '/ˈfaɪnəl/', 'adjective', '{"zh-TW":["最終的；最後的"],"en":["last; conclusive"]}', NULL, 'final decision/version', '[{"en":"The final decision rests with the board.","zh-TW":"最終決定權在董事會。"},{"en":"Submit the final version by Friday.","zh-TW":"請在週五前提交最終版本。"}]', '{"noun":"final/finale/finalist","verb":"finalize","adjective":"final","adverb":"finally"}', NULL, 2, 2747, 363),
(2748, 'final accounts', '/ˈfaɪnəl əˈkaʊnts/', 'noun', '{"zh-TW":["最終帳目；年終帳目"],"en":["the financial statements prepared at the end of a financial period"]}', NULL, 'prepare final accounts / review final accounts', '[{"en":"The final accounts were submitted to the auditors by March 31.","zh-TW":"最終帳目在3月31日前提交給了審計師。"},{"en":"Final accounts include the balance sheet and profit and loss account.","zh-TW":"最終帳目包括資產負債表和損益帳。"}]', NULL, NULL, 5, 2748, NULL),
(2749, 'final examination', '/''faɪnəl ɪɡˌzæmɪˈneɪʃən/', 'noun', '{"zh-TW":["期末考試；終期測驗"],"en":["an examination held at the end of an academic term or course"]}', NULL, 'prepare for the final examination / pass the final examination / final examination schedule', '[{"en":"She spent two weeks preparing for the final examination in organic chemistry.","zh-TW":"她花了兩週時間準備有機化學的期末考試。"},{"en":"The final examination accounts for fifty percent of the total grade.","zh-TW":"期末考試佔總成績的百分之五十。"}]', NULL, NULL, 5, 2749, NULL);